native-bench.rs.source:
use std::{fs, hint::black_box, sync::Arc, time::Instant};
use arrow::{array::*, datatypes::*, record_batch::RecordBatch};
use datafusion_common::{Result, ScalarValue};
use datafusion_physical_expr::{PhysicalExpr, expressions::{col, lit, InListExpr}};
use serde_json::json;

fn main() -> Result<()> {
    let output = std::env::args().nth(1).unwrap();
    let mut results = vec![];
    for data_type in [DataType::Float32, DataType::Float64] {
        for rows in [1, 8, 32, 64, 256, 8192] {
            for length in [1, 2, 3, 4, 128] {
                for pattern in ["mixed", "matched", "nullable"] {
                    let values = (0..rows).map(|i| {
                        if pattern == "nullable" && i % 3 == 0 { None }
                        else { Some(if pattern == "matched" { 1.0 } else { (i % 97) as f64 }) }
                    });
                    let array: ArrayRef = if data_type == DataType::Float32 {
                        Arc::new(Float32Array::from_iter(values.map(|v| v.map(|x| x as f32))))
                    } else { Arc::new(Float64Array::from_iter(values)) };
                    let schema = Arc::new(Schema::new(vec![Field::new("a", data_type.clone(), true)]));
                    let batch = RecordBatch::try_new(schema.clone(), vec![array])?;
                    let list = (1..=length).map(|i| {
                        let v = if pattern == "nullable" && i == length { None } else { Some(i as f64) };
                        lit(if data_type == DataType::Float32 {
                            ScalarValue::Float32(v.map(|x| x as f32))
                        } else { ScalarValue::Float64(v) })
                    }).collect();
                    let expr = InListExpr::try_new(col("a", &schema)?, list, false, &schema)?;
                    let check = expr.evaluate(&batch)?.into_array(rows)?;
                    let check = as_boolean_array(&check);
                    let repetitions = (2_000_000 / rows).clamp(8, 20_000);
                    let mut samples_ns = vec![];
                    for sample in 0..11 {
                        let started = Instant::now();
                        for _ in 0..repetitions {
                            black_box(expr.evaluate(black_box(&batch))?);
                        }
                        if sample >= 2 {
                            samples_ns.push(started.elapsed().as_nanos() as f64 / repetitions as f64);
                        }
                    }
                    results.push(json!({
                        "id": format!("{data_type:?}/{rows}/{length}/{pattern}"),
                        "rows": rows, "list_length": length, "pattern": pattern,
                        "true_count": check.true_count(), "null_count": check.null_count(),
                        "repetitions": repetitions, "samples_ns": samples_ns,
                    }));
                }
            }
        }
    }
    fs::write(output, serde_json::to_vec_pretty(&results).unwrap())?;
    Ok(())
}

controls-bench.rs.source:
use std::{fs, hint::black_box, sync::Arc, time::Instant};
use arrow::{array::*, datatypes::*, record_batch::RecordBatch};
use datafusion_common::{Result, ScalarValue};
use datafusion_physical_expr::{PhysicalExpr, expressions::{col, lit, InListExpr}};
use serde_json::json;

fn main() -> Result<()> {
    let output = std::env::args().nth(1).unwrap();
    let mut results = vec![];
    for data_type in [DataType::Float32, DataType::Float64, DataType::Int32, DataType::Int64, DataType::Utf8] {
        for rows in [1, 8, 32, 8192] {
            for length in [1, 3, 4] {
                for pattern in ["mixed", "nullable"] {
                  for kind in ["array", "scalar"] {
                    let id = format!("{data_type:?}/{rows}/{length}/{pattern}/{kind}");
                    if std::env::args().nth(2).is_some_and(|selected| selected != id) { continue; }
                    let values = (0..rows).map(|i| {
                        if pattern == "nullable" && i % 3 == 0 { None }
                        else { Some(if pattern == "matched" { 1.0 } else { (i % 97) as f64 }) }
                    });
                    let array: ArrayRef = match data_type {
                        DataType::Float32 => Arc::new(Float32Array::from_iter(values.map(|v| v.map(|x| x as f32)))),
                        DataType::Float64 => Arc::new(Float64Array::from_iter(values)),
                        DataType::Int32 => Arc::new(Int32Array::from_iter(values.map(|v| v.map(|x| x as i32)))),
                        DataType::Int64 => Arc::new(Int64Array::from_iter(values.map(|v| v.map(|x| x as i64)))),
                        DataType::Utf8 => Arc::new(StringArray::from_iter(values.map(|v| v.map(|x| format!("value{x}"))))),
                        _ => unreachable!(),
                    };
                    let schema = Arc::new(Schema::new(vec![Field::new("a", data_type.clone(), true)]));
                    let batch = RecordBatch::try_new(schema.clone(), vec![array])?;
                    let list = (1..=length).map(|i| {
                        let v = if pattern == "nullable" && i == length { None } else { Some(i as f64) };
                        lit(match data_type {
                            DataType::Float32 => ScalarValue::Float32(v.map(|x| x as f32)),
                            DataType::Float64 => ScalarValue::Float64(v),
                            DataType::Int32 => ScalarValue::Int32(v.map(|x| x as i32)),
                            DataType::Int64 => ScalarValue::Int64(v.map(|x| x as i64)),
                            DataType::Utf8 => ScalarValue::Utf8(v.map(|x| format!("value{x}"))),
                            _ => unreachable!(),
                        })
                    }).collect();
                    let input = if kind == "scalar" { lit(ScalarValue::try_from_array(batch.column(0), 0)?) } else { col("a", &schema)? };
                    let expr = InListExpr::try_new(input, list, false, &schema)?;
                    let check = expr.evaluate(&batch)?.into_array(rows)?;
                    let check = as_boolean_array(&check);
                    let repetitions = (2_000_000 / rows).clamp(8, 20_000);
                    let mut samples_ns = vec![];
                    for sample in 0..11 {
                        let started = Instant::now();
                        for _ in 0..repetitions {
                            black_box(expr.evaluate(black_box(&batch))?);
                        }
                        if sample >= 2 {
                            samples_ns.push(started.elapsed().as_nanos() as f64 / repetitions as f64);
                        }
                    }
                    results.push(json!({
                        "id": id, "kind": kind,
                        "rows": rows, "list_length": length, "pattern": pattern,
                        "true_count": check.true_count(), "null_count": check.null_count(),
                        "repetitions": repetitions, "samples_ns": samples_ns,
                    }));
                  }
                }
            }
        }
    }
    fs::write(output, serde_json::to_vec_pretty(&results).unwrap())?;
    Ok(())
}

measure-branches.py.source:
import json,os,statistics,subprocess
from pathlib import Path
p=Path(__file__).parent;out=p/'branch-measurements';out.mkdir()
binaries={'before':p/'before-controls-bench','extra_guard':p.parent/'float-in-guard-37ed5d8/after-controls-bench','batch_size':p/'after-controls-bench'}
cases=['Utf8/1/3/mixed/array','Utf8/8/3/nullable/array','Float32/8/3/mixed/array']
order=['before','extra_guard','batch_size','batch_size','extra_guard','before']*2
base=os.environ.copy();assert not any(k.startswith(('MALLOC_','GLIBC_','LD_PRELOAD','DECIMAL_BENCH_')) for k in base)
runs=[];canonical={}
for index,variant in enumerate(order):
 for ci,case in enumerate(cases[index%len(cases):]+cases[:index%len(cases)]):
  path=out/f'{index}-{variant}-{ci}';path.mkdir()
  cmd=['perf','stat','--json-output','-o',str(path/'counters.jsonl'),'-e','{instructions:u,cycles:u,branches:u,branch-misses:u},context-switches:u,cpu-migrations:u','--','taskset','-c','2',str(binaries[variant]),str(path/'capture.json'),case]
  subprocess.run(cmd,check=True,capture_output=True,env=base,timeout=60)
  results=json.loads((path/'capture.json').read_text());assert len(results)==1 and results[0]['id']==case
  row=results[0];check={k:v for k,v in row.items() if k!='samples_ns'}
  if case not in canonical:canonical[case]=check
  else:assert canonical[case]==check
  counters=[json.loads(x) for x in (path/'counters.jsonl').read_text().splitlines() if x.startswith('{')]
  assert len(counters)==6 and all(x['pcnt-running']==100 for x in counters)
  runs.append({'index':index,'variant':variant,'case':case,'command':cmd,'results':row,'counters':counters})
 (p/'branch-performance.json').write_text(json.dumps({'order':order,'cases':cases,'runs':runs},indent=2)+'\n')
 print(index,variant,'complete',flush=True)
summary={}
for case in cases:
 stats={}
 for v in binaries:
  rows=[r for r in runs if r['case']==case and r['variant']==v]
  medians=[statistics.median(r['results']['samples_ns']) for r in rows]
  counters={event:[next(float(c['counter-value']) for c in r['counters'] if c['event']==event) for r in rows] for event in ['instructions:u','cycles:u','branches:u','branch-misses:u']}
  stats[v]={'process_medians_ns':medians,'median_ns':statistics.median(medians),'process_counters':counters,'median_counters':{k:statistics.median(a) for k,a in counters.items()}}
 summary[case]=stats
(p/'branch-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
print('Branch counters complete',flush=True)

